import { supabase } from './supabase.js';
const app=document.querySelector('#app');
let account=null,cartItems=[],adminAllowed=false,connectionTrainerId=null;
const trainingTypes=['Online Training','Personal Fitness Guidance','Workout Planning','Nutrition Guidance','General Fitness Consultation'];
const escapeHtml=value=>String(value??'').replace(/[&<>\"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[char]));
function isPremiumMember(){const m=account?.membership||{},now=Date.now();return m.plan==='PREMIUM'&&m.status==='active'&&['paid','success','successful','succeeded','verified'].includes(String(m.payment_status||'').toLowerCase())&&(!m.starts_at||new Date(m.starts_at).getTime()<=now)&&(!m.ends_at||new Date(m.ends_at).getTime()>now)}
async function api(path,options={}){
 const body=options.body?JSON.parse(options.body):{};
 const fail=error=>{if(error)throw new Error(error.message||'Supabase request failed')};
 if(path==='/me'){
  const {data:{user},error}=await supabase.auth.getUser();fail(error);if(!user)throw new Error('Sign in required');
  const [profile,membership,history,weights,sleep,cart]=await Promise.all([
   supabase.from('profiles').select('*').eq('user_id',user.id).maybeSingle(),
   supabase.from('memberships').select('plan,starts_at,ends_at,status,payment_status').eq('user_id',user.id).order('id',{ascending:false}).limit(1).maybeSingle(),
   supabase.from('workout_history').select('*').eq('user_id',user.id).order('completed_at',{ascending:false}).limit(30),
   supabase.from('weight_entries').select('*').eq('user_id',user.id).order('recorded_at',{ascending:false}).limit(60),
   supabase.from('sleep_entries').select('*').eq('user_id',user.id).order('recorded_at',{ascending:false}).limit(30),
   supabase.from('cart_items').select('*').eq('user_id',user.id).order('id')
  ]);[profile,membership,history,weights,sleep,cart].forEach(r=>fail(r.error));
  return {user:{id:user.id,username:user.user_metadata?.full_name||user.email},profile:profile.data,membership:membership.data||{plan:'FREE',status:'active',payment_status:'not_required'},history:history.data,weights:weights.data,sleep:sleep.data,cart:cart.data};
 }
 if(path==='/profile'&&options.method==='POST'){
  const {data:{user},error}=await supabase.auth.getUser();fail(error);if(!user)throw new Error('Sign in required');
  const {error:saveError}=await supabase.from('profiles').upsert({user_id:user.id,email:user.email||'',full_name:String(body.full_name||'').trim(),age:body.age||null,gender:body.gender||null,height_cm:body.height_cm||null,weight_kg:body.weight_kg||null,fitness_goal:body.fitness_goal||'General Fitness',fitness_level:body.fitness_level||'Beginner',updated_at:new Date().toISOString()});fail(saveError);return {ok:true};
 }
 if(path==='/workouts/complete'&&options.method==='POST'){
  const {data:{user},error}=await supabase.auth.getUser();fail(error);if(!user)throw new Error('Sign in required');
  const {error:saveError}=await supabase.from('workout_history').insert({user_id:user.id,program_id:body.program_id||null,workout_name:String(body.name||'').slice(0,150),duration_minutes:Math.max(0,Number(body.duration_minutes)||0)});fail(saveError);return {ok:true};
 }
 if(path==='/track/weight'&&options.method==='POST'){
  const {data:{user},error}=await supabase.auth.getUser();fail(error);if(!user)throw new Error('Sign in required');
  const weight=Number(body.weight_kg);if(!(weight>0&&weight<1000))throw new Error('Enter a valid weight');
  const {error:saveError}=await supabase.from('weight_entries').insert({user_id:user.id,weight_kg:weight,goal_weight_kg:Number(body.goal_weight_kg)||null});fail(saveError);return {ok:true};
 }
 if(path==='/track/sleep'&&options.method==='POST'){
  const {data:{user},error}=await supabase.auth.getUser();fail(error);if(!user)throw new Error('Sign in required');
  const start=new Date('2000-01-01T'+body.sleep_time),end=new Date('2000-01-01T'+body.wake_time);if(!isFinite(start)||!isFinite(end))throw new Error('Valid sleep and wake times required');let duration=(end-start)/60000;if(duration<=0)duration+=1440;duration=Math.round(duration);
  const {error:saveError}=await supabase.from('sleep_entries').insert({user_id:user.id,sleep_time:body.sleep_time,wake_time:body.wake_time,duration_minutes:duration});fail(saveError);return {ok:true,duration_minutes:duration};
 }
 if(path==='/cart'&&(!options.method||options.method==='GET')){const {data:{user},error}=await supabase.auth.getUser();fail(error);if(!user)throw new Error('Sign in required');const r=await supabase.from('cart_items').select('*').eq('user_id',user.id).order('id');fail(r.error);return r.data;}
 if(path==='/cart/items'&&options.method==='POST'){const {data,error}=await supabase.rpc('add_fitnexa_cart_item',{p_item_type:body.item_type,p_item_id:String(body.item_id||''),p_quantity:body.quantity||1,p_billing_period:body.billing_period||'Monthly'});fail(error);return data;}
 if(path.startsWith('/cart/items/')&&options.method==='DELETE'){const {data:{user},error}=await supabase.auth.getUser();fail(error);if(!user)throw new Error('Sign in required');const id=Number(path.split('/').pop()),r=await supabase.from('cart_items').delete().eq('id',id).eq('user_id',user.id);fail(r.error);return {ok:true};}
 if(path==='/orders'&&options.method==='POST'){const {data,error}=await supabase.rpc('create_fitnexa_order',{p_customer_name:String(body.customer_name||'')});fail(error);return data;}
 if(path==='/trainers/request'&&options.method==='POST'){const {data:{session},error}=await supabase.auth.getSession();fail(error);if(!session)throw new Error('Sign in to request a trainer.');const response=await fetch('/api/trainers/requests',{method:'POST',headers:{'content-type':'application/json','authorization':'Bearer '+session.access_token},body:JSON.stringify(body)});let result={};try{result=await response.json()}catch{}if(!response.ok){const failure=new Error(result.error||'Request could not be completed.');failure.status=response.status;throw failure}return result;}
 const response=await fetch('/api'+path,{...options,headers:{'content-type':'application/json',...(sessionStorage.getItem('fitnexa-admin-session')?{'x-fitnexa-admin-token':sessionStorage.getItem('fitnexa-admin-session')}:{ }),...(options.headers||{})}});let result={};try{result=await response.json()}catch{}if(!response.ok)throw new Error(result.error||'Request failed');return result
}
function flash(text){const node=document.createElement('div');node.className='notice';node.textContent=text;node.style.cssText='position:fixed;bottom:20px;left:50%;transform:translateX(-50%);z-index:80;max-width:min(90vw,560px);box-shadow:var(--shadow)';document.body.append(node);setTimeout(()=>node.remove(),3200)}
async function loadAccount(){try{const [{data:{user},error},status]=await Promise.all([supabase.auth.getUser(),fetch('/api/auth/status').then(r=>r.json())]);if(error)throw error;adminAllowed=false;if(user){account=await api('/me');cartItems=account.cart||[]}else{account=null;cartItems=[]}if(status.admin&&location.pathname.startsWith('/admin/')&&sessionStorage.getItem('fitnexa-admin-session')){try{adminAllowed=(await api('/admin/session')).authorized===true}catch{sessionStorage.removeItem('fitnexa-admin-session')}}try{const rows=await api('/catalog?type=trainers');if(Array.isArray(rows)&&rows.length){const defaults=coaches;coaches=rows.filter(row=>row.active!==0).map(row=>{const base=defaults.find(trainer=>trainer.id===row.id)||{review:'Fictional sample review; not verified.'};let photo=base.photo;try{photo=new URL(row.photo_url).pathname.slice(1)}catch{}return {...base,id:row.id,name:row.name,photo,specialization:row.specialization,experience:row.experience||row.experience_years+' years',rating:String(row.rating||'5.0'),bio:row.biography||row.bio,qualifications:row.demo_qualifications,approach:row.training_approach,clients:row.client_types,expertise:row.areas_expertise,programs:row.training_programs,languages:row.languages,availability:row.availability,email:row.demo_email}})}}catch{}}catch{account=null;cartItems=[];adminAllowed=false}render()}
