function toolsPage(){return '<main>'+hero('FITNESS TOOLS','Make your next move informed.','Helpful estimates and gentle tracking tools. General wellness guidance only, not medical advice.')+'<section class="wrap" style="padding-bottom:80px"><div class="grid grid-2"><div class="card card-pad"><span class="eyebrow">01 · BODY MASS INDEX</span><h2 style="font-size:26px">BMI calculator</h2><div class="form-grid"><div class="field"><label>Height (cm)</label><input class="input" id="bh" type="number" placeholder="165"></div><div class="field"><label>Weight (kg)</label><input class="input" id="bw" type="number" placeholder="62"></div><button class="btn full" data-action="bmi">Calculate BMI</button></div><div id="bmi-result"></div></div><div class="card card-pad"><span class="eyebrow">02 · ENERGY NEEDS</span><h2 style="font-size:26px">Calorie estimate</h2><div class="form-grid"><div class="field"><label>Age</label><input class="input" type="number" id="age" placeholder="28"></div><div class="field"><label>Gender</label><select id="gender"><option value="female">Female</option><option value="male">Male</option></select></div><div class="field"><label>Height (cm)</label><input class="input" id="ch" type="number" placeholder="165"></div><div class="field"><label>Weight (kg)</label><input class="input" id="cw" type="number" placeholder="62"></div><div class="field full"><label>Activity level</label><select id="activity"><option value="1.2">Mostly sitting</option><option value="1.375">Light activity</option><option value="1.55">Moderate activity</option><option value="1.725">Very active</option></select></div><div class="field full"><label>Goal</label><select id="cal-goal"><option value="0">General fitness</option><option value="-250">Weight management</option><option value="200">Muscle gain</option></select></div><button class="btn full" data-action="calories">Estimate calories</button></div><div id="cal-result"></div></div><div class="card card-pad"><span class="eyebrow">03 · DAILY PROTEIN</span><h2 style="font-size:26px">Protein guide</h2><p class="muted">Estimate a daily range from your weight and goal.</p><div class="field"><label>Weight (kg)</label><input class="input" id="pw" type="number" placeholder="62"></div><div class="field" style="margin-top:14px"><label>Goal</label><select id="pg"><option value="1.2">General fitness</option><option value="1.6">Muscle gain</option><option value="1.5">Weight loss</option><option value="1.8">Strength training</option></select></div><div class="field" style="margin-top:14px"><label>Activity</label><select id="protein-activity"><option value="1">Light</option><option value="1.1">Regular training</option><option value="1.2">High training volume</option></select></div><button class="btn" style="margin-top:15px" data-action="protein">Calculate protein</button><div id="protein-result"></div></div><div class="card card-pad"><span class="eyebrow">04 · RECOVERY</span><h2 style="font-size:26px">Sleep tracker</h2><div class="form-grid"><div class="field"><label>Sleep time</label><input class="input" type="time" id="sleep-start"></div><div class="field"><label>Wake time</label><input class="input" type="time" id="sleep-end"></div><button class="btn full" data-action="save-sleep">Save sleep</button></div></div></div><div class="section-head" style="margin-top:50px"><div><span class="eyebrow">Your progress</span><h2>Weight management.</h2></div></div><div class="grid grid-2"><div class="card card-pad"><div class="form-grid"><div class="field"><label>Current weight (kg)</label><input class="input" type="number" id="weight-current" step="0.1"></div><div class="field"><label>Goal weight (kg)</label><input class="input" type="number" id="weight-goal" step="0.1"></div><button class="btn full" data-action="save-weight">Save weight</button></div><p class="muted">Weight tracking is for general self-monitoring, not medical advice.</p></div>'+chart('Weight trend')+'</div><div class="section-head" style="margin-top:50px"><div><span class="eyebrow">Cycle & wellbeing</span><h2>PCOD tracker.</h2></div></div><div class="grid grid-2"><div class="card card-pad"><h3>June 2025 · Day 12 demo</h3><div class="pcod-days">'+Array.from({length:35},(_,i)=>'<button data-action="cycle" class="'+(i<5?'period ':'')+(i===11?'today':'')+'">'+(i<30?i+1:'')+'</button>').join('')+'</div><p class="muted">Tap a date to mark it. Demo tracking only.</p></div><div class="card card-pad"><h3>Today’s check-in</h3><div class="form-grid"><div class="field"><label>Symptoms</label><select><option>None today</option><option>Cramps</option><option>Fatigue</option><option>Headache</option></select></div><div class="field"><label>Mood</label><select><option>Good</option><option>Calm</option><option>Low</option><option>Stressed</option></select></div><div class="field"><label>Exercise</label><select><option>Walk</option><option>Strength</option><option>Yoga</option><option>Rest day</option></select></div><div class="field"><label>Cycle date</label><input type="date" class="input"></div><div class="field full"><label>Notes</label><textarea placeholder="Add a note"></textarea></div><button class="btn full" data-action="save">Save demo check-in</button></div></div></div></section></main>'}
function trainersPage(){return '<main>'+hero('COACHING THAT GETS YOU','Meet your people.','Experienced, thoughtful coaches to help you make your plan personal.')+'<section class="wrap" style="padding-bottom:80px"><div class="grid grid-4">'+coaches.map(c=>'<article class="card trainer-card">'+im(c.photo)+'<div class="card-pad"><div class="rating">★ '+c.rating+' · '+c.experience+'</div><h3 style="margin:8px 0">'+c.name+'</h3><span class="pill">'+c.specialization+'</span><p class="muted" style="margin-top:13px">'+c.bio+'</p><button class="btn small" data-action="trainer" data-id="'+c.id+'">View Profile ↗</button> <button class="btn light small" data-action="connect" data-id="'+c.id+'">Connect</button></div></article>').join('')+'</div></section></main>'}
function trainerProfile(id){const c=coaches.find(trainer=>trainer.id===id);if(!c)return '<main class="wrap section"><a class="btn light" href="#trainers">← Back to Trainers</a><p class="notice" style="margin-top:20px">That trainer profile is unavailable.</p></main>';return '<main><section class="wrap section"><a class="text-link" href="#trainers">← Back to Trainers</a><div class="split" style="margin-top:24px;align-items:start"><img class="split-img" src="'+pic(c.photo,900)+'" alt="'+c.name+' profile"><div><span class="eyebrow">FITNEXA COACH · FICTIONAL DEMO PROFILE</span><h1 style="font-size:clamp(38px,5vw,60px);margin:12px 0">'+c.name+'</h1><span class="pill">'+c.specialization+'</span><p class="rating" style="margin-top:18px">★ '+c.rating+' · '+c.experience+' experience · demo rating</p><p class="muted">'+c.bio+'</p><button class="btn lime" data-action="connect" data-id="'+c.id+'">Connect With Trainer ↗</button><p class="muted" style="font-size:12px;margin-top:12px">Demo contact only. This fictional address is not monitored.</p></div></div><div class="grid grid-2" style="margin-top:30px"><div class="card card-pad"><h3>Training Approach</h3><p class="muted">'+c.approach+'</p><h3>Who They Help</h3><p class="muted">'+c.clients+'</p><h3>Areas of Expertise</h3><p class="muted">'+c.expertise+'</p><h3>Programs Offered</h3><p class="muted">'+c.programs+'</p></div><div class="card card-pad"><h3>Demo Qualifications</h3><p class="muted">'+c.qualifications+'</p><p class="notice">Fictional demonstration information. Qualifications and reviews are not verified credentials or endorsements.</p><h3>Languages</h3><p class="muted">'+c.languages+'</p><h3>Availability</h3><p class="muted">'+c.availability+'</p><h3>Demo Email</h3><p><a href="mailto:'+c.email+'">'+c.email+'</a></p><h3>Demo Review · ★★★★★</h3><p class="muted">“'+c.review+'”</p><p class="muted" style="font-size:12px">Fictional sample review. Not verified.</p></div></div><a class="btn light" href="#trainers" style="margin-top:22px">← Back to Trainers</a></section></main>'}
function trainerMailLink(form){const c=coaches.find(trainer=>trainer.id===form?.dataset.trainerId);if(!c)return;const d=new FormData(form),body=['Name: '+d.get('user_name'),'Fitness goal: '+d.get('fitness_goal'),'Preferred training type: '+d.get('training_type'),'Message: '+d.get('message'),'','This is a fictional FITNEXA demo contact; the address may not reach a real person.'].join('\n'),link=form.querySelector('[data-trainer-mail]');if(link)link.href='mailto:'+c.email+'?subject='+encodeURIComponent('FITNEXA Trainer Connection Request')+'&body='+encodeURIComponent(body)}
function connectionModal(){if(!connectionTrainerId)return '';const c=coaches.find(trainer=>trainer.id===connectionTrainerId);if(!c)return '';if(!isPremiumMember())return '<div class="modal-backdrop" data-action="close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="connect-title" data-modal-content><button class="modal-close" aria-label="Close" data-action="close">×</button><span class="eyebrow">PREMIUM COACHING</span><h2 id="connect-title" style="font-size:28px">Connect with '+c.name+'</h2><p class="muted">Trainer connection requests are available to active Premium members. Profiles remain available to everyone.</p><a class="btn lime" href="#membership" data-action="close">View Premium plan · ₹999/month ↗</a><p class="muted" style="font-size:12px;margin-top:16px">Pro remains ₹499/month. Membership access follows verified payment status.</p></section></div>';return '<div class="modal-backdrop" data-action="close"><section class="modal connection-modal" role="dialog" aria-modal="true" aria-labelledby="connect-title" data-modal-content><button class="modal-close" aria-label="Close" data-action="close">×</button><span class="eyebrow">DEMO TRAINER CONNECTION</span><h2 id="connect-title" style="font-size:28px">Connect with '+c.name+'</h2><p class="notice">Fictional trainer profile and email. Demo email is not monitored.</p><form id="trainer-connection-form" data-trainer-id="'+c.id+'"><div class="form-grid"><div class="field"><label for="connect-name">Your Full Name</label><input class="input" id="connect-name" name="user_name" autocomplete="name" required maxlength="100" value="'+escapeHtml(account?.profile?.full_name||'')+'"></div><div class="field"><label for="connect-email">Your Email</label><input class="input" id="connect-email" name="user_email" type="email" autocomplete="email" required maxlength="180" value="'+escapeHtml(account?.profile?.email||'')+'"></div><div class="field"><label>Trainer Name</label><input class="input" readonly value="'+c.name+'"></div><div class="field"><label>Trainer Demo Email</label><input class="input" readonly value="'+c.email+'"></div><div class="field full"><label for="connect-goal">Fitness Goal</label><input class="input" id="connect-goal" name="fitness_goal" required maxlength="180" placeholder="What would you like help with?"></div><div class="field full"><label for="connect-type">Preferred Training Type</label><select id="connect-type" name="training_type" required><option value="">Choose a training type</option>'+trainingTypes.map(type=>'<option>'+type+'</option>').join('')+'</select></div><div class="field full"><label for="connect-message">Message to Trainer</label><textarea id="connect-message" name="message" maxlength="1200" required placeholder="Share a little about what you are looking for."></textarea></div></div><button class="btn lime" style="margin-top:15px;width:100%">Send Connection Request</button><div class="demo-request-result" aria-live="polite"></div><p class="muted" style="font-size:12px;margin:12px 0 6px">Or contact this fictional demo address. Clicking opens your email app; it does not mean an email was sent.</p><a class="btn light" style="width:100%" href="mailto:'+c.email+'?subject='+encodeURIComponent('FITNEXA Trainer Connection Request')+'" data-trainer-mail>Contact by Email ↗</a></form></section></div>'}
function authPage(signup){return '<main class="auth-bg"><form class="card form-card" data-form="'+(signup?'signup':'login')+'"><span class="eyebrow">'+(signup?'YOUR NEXT CHAPTER':'WELCOME BACK')+'</span><h2>'+(signup?'Create your account':'Log in to FITNEXA')+'</h2><p class="muted">'+(signup?'Start building a routine that feels like yours.':'Pick up where your progress left off.')+'</p><div class="form-grid">'+(signup?'<div class="field full"><label>Full name</label><input class="input" name="name" required placeholder="Your name"></div>':'')+'<div class="field full"><label>Email</label><input class="input" name="email" type="email" autocomplete="email" required placeholder="you@example.com"></div><div class="field full"><label>Password</label><input class="input" name="password" type="password" minlength="8" autocomplete="'+(signup?'new-password':'current-password')+'" required></div><div class="notice full">Run supabase-schema.sql in your Supabase SQL Editor before using accounts. Your data is protected by row-level security.</div>'+(signup?'<div class="field"><label>Age</label><input class="input" name="age" type="number" min="13" required></div><div class="field"><label>Gender</label><select name="gender"><option>Prefer not to say</option><option>Female</option><option>Male</option><option>Non-binary</option></select></div><div class="field"><label>Height (cm)</label><input class="input" name="height" type="number" required></div><div class="field"><label>Weight (kg)</label><input class="input" name="weight" type="number" required></div><div class="field"><label>Fitness goal</label><select name="goal"><option>Weight Management</option><option>Muscle Gain</option><option>General Fitness</option><option>Strength</option><option>Endurance</option></select></div><div class="field"><label>Fitness level</label><select name="level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></div>':'')+'</div><button class="btn lime" style="width:100%;margin-top:16px">'+(signup?'Create account':'Log in')+'</button><p class="muted" style="text-align:center;margin:20px 0 0">'+(signup?'Already have an account? <a href="#login"><b>Log in</b></a>':'Don’t have an account? <a href="#signup"><b>Sign up</b></a>')+'</p></form></main>'}
function plans(){let vals={FREE:0,PRO:499,PREMIUM:999};return '<main>'+hero('MEMBERSHIP','A plan for your next step.','Start free, then choose more support when you are ready. No payment is processed in this demo.')+'<section class="wrap" style="padding-bottom:80px"><div style="display:flex;justify-content:center;margin-bottom:25px"><div class="plan-toggle"><button class="'+(period==='Monthly'?'active':'')+'" data-period="Monthly">Monthly</button><button class="'+(period==='Yearly'?'active':'')+'" data-period="Yearly">Yearly · save 20%</button></div></div><div class="grid grid-3">'+[['FREE','A strong place to begin.',['Basic workouts','Basic fitness tools','Nutrition tips']],['PRO','For your next level.',['Advanced workouts','Nutrition plans','Progress tracking','NEXA AI assistant']],['PREMIUM','More personal support.',['Everything in Pro','Trainer connection','Advanced programs','Personalized features']]].map((x,i)=>'<article class="card plan '+(i===1?'featured':'')+'">'+(i===1?'<span class="pill">MOST POPULAR</span>':'')+'<h3 style="margin-top:15px">'+x[0]+'</h3><p class="muted">'+x[1]+'</p><div class="plan-price">₹'+(vals[x[0]]===0?'0':period==='Yearly'?Math.round(vals[x[0]]*.8):vals[x[0]])+'<span style="font:500 13px DM Sans;color:#777"> / '+(x[0]==='FREE'?'forever':period==='Yearly'?'month, billed yearly':'month')+'</span></div><ul>'+x[2].map(f=>'<li>'+f+'</li>').join('')+'</ul><button class="btn '+(i===1?'lime':'')+'" style="width:100%" data-plan="'+x[0]+'">Choose '+x[0]+' ↗</button></article>').join('')+'</div><div class="card card-pad" style="margin-top:24px"><h3>Compare plans</h3><div class="table-wrap"><table class="table"><thead><tr><th>Included</th><th>Free</th><th>Pro</th><th>Premium</th></tr></thead><tbody>'+[['Workout library','Basic','Advanced','Advanced + custom'],['Nutrition guidance','Tips','Plans','Personalized'],['Progress tracking','Basic','✓','Advanced'],['Trainer connection','—','—','✓'],['NEXA AI','—','✓','✓']].map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></div></section></main>'}
function checkoutLegacy(){let price=plan==='FREE'?0:plan==='PRO'?499:999,amount=period==='Yearly'?Math.round(price*.8)*12:price;return '<main>'+hero('SECURE CHECKOUT','Your plan, your next step.','Review your demo order. No payment details will be submitted or charged.')+'<section class="wrap" style="padding-bottom:80px"><div class="checkout-grid"><div class="card card-pad"><span class="eyebrow">01 · PAYMENT METHOD</span><h2 style="font-size:26px">Choose how to pay</h2><div class="payment-options">'+['UPI','Credit / Debit Card','Net Banking','Wallets'].map(x=>'<button class="pay-option '+(pay===x?'active':'')+'" data-pay="'+x+'">◉ &nbsp;'+x+'</button>').join('')+'</div><div class="card card-pad" style="margin-top:18px;background:#f7f8f4"><b>'+pay+'</b><p class="muted">Payment details appear here after gateway integration.</p></div><h3 style="margin-top:25px">Payment status demo</h3><div class="tag-row"><span class="status">Successful</span><span class="status pending">Pending</span><span class="tag">Failed</span></div><button class="btn lime" style="width:100%;margin-top:20px" data-action="payment">Proceed to Payment · ₹'+amount+'</button><div id="payment-message"></div></div><aside class="card card-pad"><span class="eyebrow">ORDER SUMMARY</span><h2 style="font-size:26px">'+plan+' plan</h2><p class="muted">'+period+' billing</p><div style="border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:17px 0;margin:18px 0"><div style="display:flex;justify-content:space-between"><span>'+plan+' membership</span><b>₹'+amount+'</b></div><small class="muted">'+(period==='Yearly'?'Billed yearly':'Billed monthly')+'</small></div><div style="display:flex;justify-content:space-between;font-size:19px"><b>Total</b><b>₹'+amount+'</b></div><div class="notice" style="margin-top:18px">Demo checkout only. Razorpay or Stripe can be connected later through a secure backend.</div><p style="margin-top:20px"><span class="muted">Account</span><br><b>FITNEXA demo member</b><br><small class="muted">member@example.com</small></p></aside></div></section></main>'}
function assistant(){return '<main>'+hero('FITNEXA CUSTOMER HELP','Ask about products and more.','NEXA answers from the Fitnexa sample catalog and customer knowledge base. It does not provide medical advice.')+'<section class="wrap" style="padding-bottom:80px"><div class="chat-shell"><div class="chat-box"><div class="chat-top"><div class="ai-dot">N</div><div><b>NEXA AI</b><div class="muted" style="font-size:11px">Fitness and nutrition guide</div></div><span class="pill" style="margin-left:auto">● Ready</span></div><div class="messages" id="messages"><div class="bubble">Hi, I’m NEXA. Ask about a product’s ingredients, nutrition, size, use or care. I’ll tell you when a detail is only illustrative or not available.</div></div><form class="chat-form" id="chat-form"><input name="message" placeholder="Ask about workouts, form or nutrition..." required><button class="btn lime">Send ↗</button></form></div><aside><h3>Try asking</h3><div class="suggestions">'+['What ingredients are in the plant protein?','How much does FX-001 cost?','Which products contain peanuts?','Do you have a return policy?'].map(x=>'<button data-prompt="'+x+'">“'+x+'”</button>').join('')+'</div><a class="btn light small" style="margin-top:14px" href="#products">Browse all products ↗</a><div class="notice" style="margin-top:15px">Product prices and nutrition are sample data, not verified live listings. For allergies or medical concerns, check the final label and consult a qualified professional.</div></aside></div></section></main>'}
function about(){return '<main>'+hero('OUR STORY','Better habits. Stronger lives.','FITNEXA is your supportive space to build strength, confidence, and wellbeing — one realistic choice at a time.')+'<section class="wrap section split"><div>'+im('photo-1526506118085-60ce8714f8c5',900)+'</div><div><span class="eyebrow">What is FITNEXA?</span><h2>Fitness + technology, made human.</h2><p class="muted">We bring training, nutrition, and everyday wellness tools together so you can spend less time guessing and more time growing.</p><h3>Our mission</h3><p class="muted">Make practical, inclusive fitness guidance easier to access and easier to keep doing.</p><h3>Our vision</h3><p class="muted">A world where feeling stronger is not reserved for a few. Good health is built through small, sustainable habits.</p></div></section><section class="section section-alt"><div class="wrap"><div class="section-head"><div><span class="eyebrow">The people behind the plan</span><h2>Meet our founding team.</h2></div></div><div class="grid grid-3">'+[['Nikhil Rao','Co-founder · Training','photo-1500648767791-00dcc994a43e'],['Sana Verma','Co-founder · Community','photo-1534528741775-53994a69daeb'],['Dev Shah','Product · Technology','photo-1560250097-0b93528c311a']].map(x=>'<div class="card card-pad">'+im(x[2],400)+'<h3 style="margin-top:17px">'+x[0]+'</h3><p class="muted">'+x[1]+'</p></div>').join('')+'</div></div></section><section class="section"><div class="wrap quote-card"><span class="eyebrow">Our promise</span><blockquote>Train Smart. Eat Better. Become Stronger.</blockquote><p class="muted">A little better, every day.</p></div></section></main>'}
function contact(){return '<main>'+hero('WE WOULD LOVE TO HEAR FROM YOU','Let’s make a connection.','Questions about a workout, your next plan, or just want to say hello? Drop our demo team a note.')+'<section class="wrap section split"><div><span class="eyebrow">GET IN TOUCH</span><h2>Here for your next step.</h2><p><b>Email</b><br><a href="mailto:support@fitnexa-demo.com">support@fitnexa-demo.com</a></p><p><b>Phone</b><br><a href="tel:+919876543210">+91 98765 43210</a></p><p><b>Visit</b><br>FITNEXA Fitness Center, Sector 62,<br>Noida, Uttar Pradesh, India</p><div class="quote-card"><b>We’re listening.</b><p class="muted" style="margin:5px 0 0">Demo contact form · no email is sent.</p></div></div><form class="card card-pad" data-form="contact"><h2 style="font-size:28px">Send us a message</h2><div class="field"><label>Name</label><input class="input" name="name" required></div><div class="field"><label>Email</label><input class="input" name="email" type="email" required></div><div class="field"><label>Subject</label><input class="input" name="subject" required></div><div class="field"><label>Message</label><textarea name="message" required></textarea></div><button class="btn lime">Send message ↗</button><div class="form-message muted"></div></form></section></main>'}
function resources(){return '<main>'+hero('FITNEXA LEARN','Get curious. Get stronger.','Free videos and guides to help you learn at your own pace.')+'<section class="wrap" style="padding-bottom:80px"><div class="grid grid-3">'+[['Strength training fundamentals','Training','photo-1583454110551-21f2fa2afe61'],['Build a balanced plate','Nutrition','photo-1512621776951-a57141f2eefd'],['Mobility for recovery','Recovery','photo-1518611012118-696072aa579a'],['Beginner gym confidence','Getting started','photo-1534438327276-14e5300c3a48'],['Make sleep work for you','Recovery','photo-1506126613408-eca07ce68773'],['Simple meal prep ideas','Nutrition','photo-1490645935967-10de6ba17061']].map(v=>'<article class="card"><div class="video-thumb">'+im(v[2])+'<a class="play" target="_blank" rel="noreferrer" href="https://www.youtube.com/results?search_query='+encodeURIComponent(v[0]+' fitness')+'">▶</a></div><div class="card-pad"><span class="eyebrow">'+v[1]+'</span><h3>'+v[0]+'</h3><a class="text-link" target="_blank" rel="noreferrer" href="https://www.youtube.com/results?search_query='+encodeURIComponent(v[0]+' fitness')+'">Watch resource ↗</a></div></article>').join('')+'</div></section></main>'}
function metric(label,value,caption){return '<div class="stat-card"><small>'+label+'</small><strong>'+value+'</strong><span>'+caption+'</span></div>'}
function dashPage(){let profile=account?.profile||{},weight=account?.weights?.[0]?.weight_kg||profile.weight_kg,latestSleep=account?.sleep?.[0],workoutsDone=account?.history||[];let items=['Overview','My Workouts','Nutrition','BMI Calculator','Calorie Tracker','Protein Tracker','Sleep Tracker','Weight Management','PCOD Tracker','AI Assistant','Trainers','Membership','Profile','Settings'];let inner=dash==='Overview'?'<div class="stats-grid">'+metric('Current weight',weight?weight+' kg':'Not recorded','Saved profile data')+metric('BMI',weight&&profile.height_cm?(weight/((profile.height_cm/100)**2)).toFixed(1):'Add height','Estimate only')+metric('Daily calories','Use fitness tools','General estimate')+metric('Protein target',weight?Math.round(weight*1.2)+' g/day':'Add weight','General estimate')+'</div><div class="grid grid-2">'+chart('Weekly workout progress')+'<div class="card card-pad"><span class="eyebrow">TODAY · TUESDAY</span><h3>Upper body strength</h3><p class="muted">35 min · Intermediate · 6 movements</p><div class="progress"><span style="width:40%"></span></div><p>2 of 5 workouts this week</p><button class="btn small" data-action="start" data-name="Upper body strength">Continue workout ↗</button></div><div class="card card-pad"><span class="eyebrow">NUTRITION TODAY</span><h3>On your way.</h3><p class="muted">Calories 1,420 / 2,150 · Protein 70 / 130g</p><div class="progress"><span style="width:58%"></span></div><p>Water 1.2 / 2.5 L</p><a class="text-link" href="#nutrition">Open nutrition ↗</a></div><div class="card card-pad"><span class="eyebrow">REST & RECOVERY</span><h3>Sleep 7h 18m</h3><p class="muted">Your goal is 8 hours. A calm wind-down makes a difference.</p><span class="badge">✦ 7-day workout streak</span></div></div>':dashPanel(dash);return '<main class="dashboard"><aside class="side-nav"><div class="eyebrow">YOUR SPACE</div>'+items.map(x=>'<button class="'+(dash===x?'selected':'')+'" data-dash="'+x+'">'+x+'</button>').join('')+'</aside><section class="dash-main"><div class="dash-header"><div><span class="eyebrow">TUESDAY, JUNE 17</span><h1>Good morning, '+(profile.full_name||account?.user?.username||'there')+' <span style="color:#9bbd50">✦</span></h1><p class="muted">Small steps are adding up. Keep going.</p></div><span class="pill">'+(account?.membership?.plan||'FREE')+' MEMBER</span></div><h2 style="font-size:26px">'+dash+'</h2>'+inner+'</section></main>'}
function dashPanel(x){const p=account?.profile||{},history=account?.history||[],weights=account?.weights||[],sleeps=account?.sleep||[];if(x==='My Workouts')return '<div class="card card-pad"><h3>Workout history</h3>'+(history.length?history.map(w=>'<p>'+w.workout_name+' <span class="muted">· '+new Date(w.completed_at).toLocaleDateString()+'</span></p>').join(''):'<p class="muted">Completed workouts will appear here.</p>')+'<a class="btn small" href="#workouts">Browse workouts</a></div>';if(x==='Nutrition')return '<div class="card card-pad"><h3>Nutrition tools</h3><p class="muted">Use the calculators for general calorie and protein estimates.</p><a class="btn small" href="#tools">Open fitness tools</a></div>';if(x==='AI Assistant')return '<div class="notice">NEXA is connected to the fitness assistant. <a href="#assistant"><b>Open assistant ↗</b></a></div>';if(x==='Trainers')return '<a class="btn" href="#trainers">Browse trainers ↗</a>';if(x==='Membership')return '<div class="card card-pad"><span class="pill">'+(account?.membership?.plan||'FREE')+' · '+(account?.membership?.status||'active')+'</span><p class="muted" style="margin-top:14px">Paid access requires verified payment.</p><a class="btn small" href="#membership">View plans</a></div>';if(x==='BMI Calculator'||x==='Calorie Tracker'||x==='Protein Tracker')return '<a class="btn" href="#tools">Open fitness calculators ↗</a>';if(x==='Sleep Tracker')return '<div class="card card-pad"><h3>Saved sleep entries</h3>'+(sleeps.length?sleeps.map(t=>'<p>'+Math.floor(t.duration_minutes/60)+'h '+t.duration_minutes%60+'m <span class="muted">· '+new Date(t.recorded_at).toLocaleDateString()+'</span></p>').join(''):'<p class="muted">No sleep entries saved yet.</p>')+'<a class="btn small" href="#tools">Log sleep</a></div>';if(x==='Weight Management')return '<div class="card card-pad"><h3>Saved weight entries</h3>'+(weights.length?weights.map(t=>'<p>'+t.weight_kg+' kg <span class="muted">· '+new Date(t.recorded_at).toLocaleDateString()+'</span></p>').join(''):'<p class="muted">No weight entries saved yet.</p>')+'<a class="btn small" href="#tools">Log weight</a></div>';if(x==='PCOD Tracker')return '<div class="notice">This tracker is not connected to account storage.</div>';if(x==='Profile'||x==='Settings')return '<form class="card card-pad" id="profile-edit-form"><h3>'+x+' details</h3><div class="grid grid-2"><div class="field"><label>Name</label><input class="input" name="full_name" value="'+(p.full_name||'')+'" required></div><div class="field"><label>Email</label><input class="input" name="email" type="email" value="'+(p.email||'')+'"></div><div class="field"><label>Fitness goal</label><select name="fitness_goal">'+['Weight Management','Muscle Gain','General Fitness','Strength','Endurance'].map(g=>'<option '+(p.fitness_goal===g?'selected':'')+'>'+g+'</option>').join('')+'</select></div><div class="field"><label>Fitness level</label><select name="fitness_level">'+['Beginner','Intermediate','Advanced'].map(g=>'<option '+(p.fitness_level===g?'selected':'')+'>'+g+'</option>').join('')+'</select></div><button class="btn">Save profile</button></div></form>';return '<div class="card card-pad">'+x+' · Your saved fitness data appears here.</div>'}

function adminPage(){if(!location.pathname.startsWith('/admin/'))history.replaceState(null,'','/admin/login');if(location.pathname.includes('/dashboard')&&!adminAllowed)history.replaceState(null,'','/admin/login');if(location.pathname.includes('/dashboard')&&adminAllowed)return privateAdminDashboard();return privateAdminLogin()}
function privateAdminLogin(){return '<main class="auth-bg"><section class="card form-card"><span class="eyebrow">PRIVATE ADMIN</span><h2>Admin access</h2><p class="muted">Administration is restricted to the authenticated project owner account.</p>'+(adminAllowed?'<button class="btn lime" data-admin-enter>Open admin dashboard</button>':'<div class="notice">Sign in to Websim with the project owner account. Fitnexa admin access is verified by the server.</div><button class="btn lime" data-admin-login>Verify owner account</button>')+'</section></main>'}
function privateAdminDashboard(){return '<main class="dashboard admin-layout"><aside class="side-nav"><div class="eyebrow">PRIVATE ADMIN</div><button class="btn light small" data-admin-logout>Sign out of admin</button></aside><section class="dash-main"><div class="dash-header"><div><span class="eyebrow">FITNEXA ADMIN</span><h1>Content management</h1><p class="muted">Changes are saved to the private project database.</p></div><span class="pill">OWNER VERIFIED</span></div><div class="card card-pad"><div class="field"><label>Collection</label><select id="admin-collection"><option value="users">Users</option><option value="memberships">Memberships</option><option value="exercises">Exercises</option><option value="workout_programs">Workout programs</option><option value="foods">Nutrition / foods</option><option value="trainers">Trainers</option><option value="products">Products</option><option value="trainer_requests">Trainer requests</option><option value="orders">Orders</option><option value="payments">Payments</option></select></div><div class="table-wrap" id="admin-records"><p class="muted">Loading records…</p></div></div><form class="card card-pad" id="admin-record-form" style="margin-top:18px"><h3>Add or update a record</h3><p class="muted">Use JSON fields matching the selected collection. IDs are required for editable content.</p><textarea class="input" name="record" rows="8" placeholder="{ &quot;id&quot;: &quot;example&quot;, &quot;name&quot;: &quot;Example&quot; }" required></textarea><button class="btn lime" style="margin-top:14px">Save record</button></form></section></main>'}
async function loadAdminCollection(){const select=document.querySelector('#admin-collection'),target=document.querySelector('#admin-records');if(!select||!target||!adminAllowed)return;target.innerHTML='<p class="muted">Loading…</p>';try{const rows=await api('/admin/'+select.value);target.innerHTML=Array.isArray(rows)&&rows.length?'<table class="table"><thead><tr><th>Record</th><th>Details</th><th></th></tr></thead><tbody>'+rows.map(row=>'<tr><td><b>'+String(row.name||row.full_name||row.id||row.user_id||'Record').replace(/[<>]/g,'')+'</b></td><td><code>'+JSON.stringify(row).replace(/[<>]/g,'')+'</code></td><td>'+(['exercises','workout_programs','foods','trainers','products'].includes(select.value)?'<button class="btn light small" data-admin-delete="'+String(row.id).replace(/[<>]/g,'')+'">Delete</button>':select.value==='trainer_requests'?'<div><b>'+String(row.status||'Pending').replace(/[<>]/g,'')+'</b><br><button class="btn light small" data-request-status="Accepted" data-request-id="'+String(row.id).replace(/[<>]/g,'')+'">Accept</button> <button class="btn light small" data-request-status="Rejected" data-request-id="'+String(row.id).replace(/[<>]/g,'')+'">Reject</button></div>':'')+'</td></tr>').join('')+'</tbody></table>':'<p class="muted">No records yet.</p>'}catch(error){target.textContent=error.message}}
function orderAmount(){return cartItems.reduce((sum,item)=>sum+item.unit_price*item.quantity*(item.item_type==='membership'&&item.billing_period==='Yearly'?12:1),0)}
function checkout(){const amount=orderAmount();return '<main>'+hero('YOUR CART','Review your order.','Memberships and products stay in your cart until checkout.')+'<section class="wrap" style="padding-bottom:80px"><div class="checkout-grid"><div class="card card-pad"><span class="eyebrow">CART · '+cartItems.length+' ITEMS</span><h2 style="font-size:28px">Order summary</h2>'+(cartItems.length?'<div class="table-wrap"><table class="table"><thead><tr><th>Item</th><th>Billing</th><th>Qty</th><th>Price</th></tr></thead><tbody>'+cartItems.map(i=>'<tr><td><b>'+i.name+'</b><br><button class="text-link" data-cart-remove="'+i.id+'">Remove</button></td><td>'+(i.billing_period||'—')+'</td><td>'+i.quantity+'</td><td>₹'+(i.unit_price*i.quantity*(i.item_type==='membership'&&i.billing_period==='Yearly'?12:1))+'</td></tr>').join('')+'</tbody></table></div>':'<p class="muted">Your cart is empty. Sign in to save items across visits.</p>')+'<div class="field" style="margin-top:22px"><label>Name for order</label><input class="input" data-customer-name value="'+(account?.profile?.full_name||'')+'" placeholder="Your name"></div><a class="text-link" href="#membership" style="margin-top:16px">← Browse membership plans</a></div><aside class="card card-pad"><span class="eyebrow">TOTAL</span><h2 style="font-size:34px">₹'+amount+'</h2><p class="muted">Payment status remains pending until a gateway verifies payment.</p><div class="notice">Secure payment integration is not configured. No payment will be claimed or verified here.</div><button class="btn lime" style="width:100%;margin-top:20px" data-action="to-payment" '+(!cartItems.length?'disabled':'')+'>Create order ↗</button></aside></div></section></main>'}
function paymentPage(){const id=localStorage.getItem('fitnexa-order-id'),total=Number(localStorage.getItem('fitnexa-order-total')||0);return '<main>'+hero('PAYMENT','Order pending.','A payment provider is not configured. Your order will remain pending until a provider verifies the transaction.')+'<section class="wrap" style="padding-bottom:80px"><div class="card card-pad" style="max-width:760px;margin:auto"><span class="eyebrow">ORDER · '+(id||'NOT FOUND')+'</span><h2 style="font-size:30px">₹'+total+'</h2><div class="notice">No payment was taken or confirmed. Paid memberships do not activate without server-side payment verification.</div><p style="margin-top:20px"><a class="btn light" href="#checkout">Return to cart</a> <a class="btn lime" href="#dashboard">Open dashboard</a></p></div></section></main>'}
function confirmationPage(){return '<main>'+hero('ORDER STATUS','Payment pending.','This project has no payment gateway configured; orders remain pending until server-side verification is integrated.')+'<section class="wrap" style="padding-bottom:80px"><div class="card card-pad" style="max-width:760px;margin:auto"><div class="notice">No paid membership has been activated. You can return to your dashboard or cart.</div><p style="margin-top:20px"><a class="btn light" href="#checkout">Open cart</a> <a class="btn lime" href="#dashboard">Open dashboard</a></p></div></section></main>'}
function render(){let h=location.hash.slice(1)||'home',p=h.split('/'),page=location.pathname.startsWith('/admin/')?'admin':p[0];if(page==='dashboard'&&!account){location.hash='login';page='login'}let body=page==='home'?home():page==='products'?productsPage():page==='workouts'?workoutPage():page==='nutrition'?nutritionPage():page==='tools'?toolsPage():page==='trainers'?trainersPage():page==='trainer'?trainerProfile(decodeURIComponent(p[1]||'')):page==='membership'?plans():page==='checkout'?checkout():page==='payment'?paymentPage():page==='confirmation'?confirmationPage():page==='assistant'?assistant():page==='signup'?authPage(true):page==='login'?authPage(false):page==='dashboard'?dashPage():page==='admin'?adminPage():page==='about'?about():page==='contact'?contact():page==='resources'?resources():home();app.innerHTML=page==='admin'?body:header()+body+connectionModal()+footer();if(connectionTrainerId&&isPremiumMember())trainerMailLink(document.querySelector('#trainer-connection-form'));window.scrollTo(0,0);document.querySelectorAll('[data-filter]').forEach(el=>{if(el.dataset.filter==='level')el.value=level;if(el.dataset.filter==='muscle')el.value=muscle;if(el.dataset.filter==='type')el.value=type;if(el.dataset.filter==='duration')el.value=duration});if(page==='admin'&&adminAllowed)loadAdminCollection()}
function botAnswer(text){const q=text.toLowerCase();if(/medical|injur|pregnan|diagnos|disease/.test(q))return 'I can provide general fitness information, not medical advice. Consult a qualified health professional for medical concerns.';return 'Ask me about exercise, workout planning, form, nutrition, protein or calories. Answers are general information and not medical advice.'}
app.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b){if(e.target.classList?.contains('modal-backdrop')){connectionTrainerId=null;e.target.remove()}return;}if(b.dataset.dash){dash=b.dataset.dash;render()}if(b.dataset.filter)return;if(b.dataset.adminLogin)api('/admin/login',{method:'POST',body:'{}'}).then(result=>{sessionStorage.setItem('fitnexa-admin-session',result.token);history.pushState(null,'','/admin/dashboard');loadAccount()}).catch(error=>flash(error.message));if(b.dataset.adminLogout)api('/admin/logout',{method:'POST',body:'{}'}).finally(()=>{sessionStorage.removeItem('fitnexa-admin-session');adminAllowed=false;history.pushState(null,'','/admin/login');render()});if(b.dataset.adminEnter){history.pushState(null,'','/admin/dashboard');render()}if(b.dataset.adminDelete){const kind=document.querySelector('#admin-collection')?.value;api('/admin/'+kind+'/'+encodeURIComponent(b.dataset.adminDelete),{method:'DELETE'}).then(loadAdminCollection).catch(error=>flash(error.message))}if(b.dataset.requestStatus){api('/admin/trainer_requests/'+encodeURIComponent(b.dataset.requestId),{method:'PATCH',body:JSON.stringify({status:b.dataset.requestStatus})}).then(()=>{flash('Trainer request status updated.');loadAdminCollection()}).catch(error=>flash(error.message))}if(b.dataset.plan){plan=b.dataset.plan;api('/cart/items',{method:'POST',body:JSON.stringify({item_type:'membership',item_id:plan,billing_period:period})}).then(rows=>{cartItems=rows;location.hash='checkout'}).catch(error=>{flash(error.message);if(!account)location.hash='login'})}if(b.dataset.productAdd)api('/cart/items',{method:'POST',body:JSON.stringify({item_type:'product',item_id:b.dataset.productAdd,quantity:1})}).then(rows=>{cartItems=rows;flash('Added to your cart.');render()}).catch(error=>{flash(error.message);if(!account)location.hash='login'});if(b.dataset.cartRemove)api('/cart/items/'+b.dataset.cartRemove,{method:'DELETE'}).then(()=>loadAccount()).catch(error=>flash(error.message));if(b.dataset.period){period=b.dataset.period;render()}if(b.dataset.prompt){const input=document.querySelector('#chat-form input');if(input){input.value=b.dataset.prompt;document.querySelector('#chat-form').requestSubmit()}}if(b.dataset.action){const a=b.dataset.action;if(a==='trainer'){location.hash='trainer/'+encodeURIComponent(b.dataset.id);return}if(a==='connect'){connectionTrainerId=b.dataset.id;app.insertAdjacentHTML('beforeend',connectionModal());trainerMailLink(document.querySelector('#trainer-connection-form'));document.querySelector('#connect-title')?.focus();return}if(a==='close'){connectionTrainerId=null;b.closest('.modal-backdrop')?.remove();return}if(a==='menu')document.querySelector('#navlinks')?.classList.toggle('open');if(a==='logout')supabase.auth.signOut().then(()=>{account=null;cartItems=[];location.hash='home';render()}).catch(error=>flash(error.message));if(a==='to-payment'){const name=document.querySelector('[data-customer-name]');api('/orders',{method:'POST',body:JSON.stringify({customer_name:name?.value.trim()||''})}).then(order=>{localStorage.setItem('fitnexa-order-id',order.id);localStorage.setItem('fitnexa-order-total',String(order.total));cartItems=[];location.hash='payment'}).catch(error=>{flash(error.message);if(!account)location.hash='login'})}if(a==='confirm-payment')flash('Order remains pending until a payment provider verifies it.');if(a==='start'){if(!account){flash('Sign in to record completed workouts.');location.hash='login'}else api('/workouts/complete',{method:'POST',body:JSON.stringify({name:b.dataset.name})}).then(()=>{flash('Workout saved to your history.');loadAccount()}).catch(error=>flash(error.message))}if(a==='save-weight'){api('/track/weight',{method:'POST',body:JSON.stringify({weight_kg:Number(document.querySelector('#weight-current')?.value),goal_weight_kg:Number(document.querySelector('#weight-goal')?.value)})}).then(()=>{flash('Weight entry saved.');loadAccount()}).catch(error=>flash(error.message))}if(a==='save-sleep'){api('/track/sleep',{method:'POST',body:JSON.stringify({sleep_time:document.querySelector('#sleep-start')?.value,wake_time:document.querySelector('#sleep-end')?.value})}).then(r=>{flash('Sleep saved: '+Math.floor(r.duration_minutes/60)+'h '+r.duration_minutes%60+'m');loadAccount()}).catch(error=>flash(error.message))}if(a==='bmi'){const h=Number(document.querySelector('#bh').value),w=Number(document.querySelector('#bw').value),out=document.querySelector('#bmi-result');if(h>0&&w>0){const n=w/((h/100)**2),category=n<18.5?'Below healthy range':n<25?'Healthy range':n<30?'Above healthy range':'High BMI range';out.innerHTML='<div class="tool-result"><strong>'+n.toFixed(1)+'</strong><br>'+category+'<p class="muted">General estimate, not a diagnosis.</p></div>'}else out.textContent='Enter a valid height and weight.'}if(a==='calories'){const age=Number(document.querySelector('#age').value),h=Number(document.querySelector('#ch').value),w=Number(document.querySelector('#cw').value),gender=document.querySelector('#gender').value,m=Number(document.querySelector('#activity').value),out=document.querySelector('#cal-result');if(age>0&&h>0&&w>0){const bmr=10*w+6.25*h-5*age+(gender==='male'?5:-161),goal=Number(document.querySelector('#cal-goal').value),value=Math.round(bmr*m+goal);out.innerHTML='<div class="tool-result"><strong>'+value.toLocaleString()+' kcal</strong><br>Estimated daily maintenance calories<p class="muted">General estimate, not medical advice.</p></div>'}else out.textContent='Enter age, height and weight.'}if(a==='protein'){const w=Number(document.querySelector('#pw').value),factor=Number(document.querySelector('#pg').value),activity=Number(document.querySelector('#protein-activity').value),out=document.querySelector('#protein-result');if(w>0)out.innerHTML='<div class="tool-result"><strong>'+Math.round(w*factor*activity)+'–'+Math.round(w*(factor+0.2)*activity)+' g/day</strong><br>Estimated protein range; individual needs vary.</div>';else out.textContent='Enter a valid weight.'}if(a==='connect'){if(!account){flash('Sign in to request a trainer.');location.hash='login'}else api('/trainers/request',{method:'POST',body:JSON.stringify({trainer_id:'coach-'+b.dataset.id})}).then(()=>flash('Trainer request saved.')).catch(error=>flash(error.message))}if(a==='cycle')b.classList.toggle('period');if(a==='save'||a==='demo')flash('This section is not connected to account storage.');if(a==='close')b.closest('.modal-backdrop')?.remove()}if(b.dataset.admin)flash('Use the collection selector to manage content.');});
app.addEventListener('input',e=>{if(e.target.closest('#trainer-connection-form'))trainerMailLink(e.target.closest('#trainer-connection-form'));const f=e.target.dataset.filter;if(f==='search'){query=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('[data-filter="search"]');input?.focus();input?.setSelectionRange(pos,pos)}if(e.target.dataset.productSearch!==undefined){productQuery=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('[data-product-search]');input?.focus();input?.setSelectionRange(pos,pos)}});
app.addEventListener('change',e=>{if(e.target.closest('#trainer-connection-form'))trainerMailLink(e.target.closest('#trainer-connection-form'));const f=e.target.dataset.filter;if(e.target.id==='admin-collection')loadAdminCollection();if(f==='level')level=e.target.value;if(f==='muscle')muscle=e.target.value;if(f==='type')type=e.target.value==='All workout types'?'All':e.target.value;if(f==='duration')duration=e.target.value;if(f)render()});
app.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id==='trainer-connection-form'){if(!isPremiumMember()){connectionTrainerId=form.dataset.trainerId;render();return}const c=coaches.find(trainer=>trainer.id===form.dataset.trainerId),d=Object.fromEntries(new FormData(form));d.user_name=String(d.user_name||'').trim();d.user_email=String(d.user_email||'').trim();d.fitness_goal=String(d.fitness_goal||'').trim();d.message=String(d.message||'').trim();if(!c||!d.user_name||!d.user_email||!/^\S+@\S+\.\S+$/.test(d.user_email)||!d.fitness_goal||!trainingTypes.includes(d.training_type)||!d.message){form.reportValidity();return}const submit=form.querySelector('button[type="submit"],button:not([data-trainer-mail])'),result=form.querySelector('.demo-request-result'),payload={trainer_id:c.id,trainer_name:c.name,trainer_email:c.email,user_name:d.user_name,user_email:d.user_email,fitness_goal:d.fitness_goal,training_type:d.training_type,message:d.message};if(submit)submit.disabled=true;result.textContent='Submitting request…';api('/trainers/request',{method:'POST',body:JSON.stringify(payload)}).then(()=>{result.className='notice demo-request-result';result.textContent='Your demo connection request has been submitted successfully. This is a demonstration feature; the trainer\x27s email is not monitored.';if(submit)submit.disabled=true}).catch(error=>{if(error.status===404||error instanceof TypeError){try{const requests=JSON.parse(localStorage.getItem('fitnexa-demo-requests')||'[]');requests.push({...payload,request_id:crypto.randomUUID(),created_at:new Date().toISOString(),status:'Pending'});localStorage.setItem('fitnexa-demo-requests',JSON.stringify(requests));result.className='notice demo-request-result';result.textContent='Demo-only request saved in this browser. It was not saved to the FITNEXA backend and is not permanent across browsers or cleared storage.';if(submit)submit.disabled=true;return}catch{}}result.className='notice demo-request-result';result.textContent=error.message||'Could not submit the request. Please try again.';if(submit)submit.disabled=false});return}if(form.id==='admin-record-form'){try{const record=JSON.parse(form.elements.record.value),kind=document.querySelector('#admin-collection').value;api('/admin/'+kind,{method:'POST',body:JSON.stringify(record)}).then(()=>{flash('Record saved.');form.reset();loadAdminCollection()}).catch(error=>flash(error.message))}catch{flash('Enter valid JSON for this collection.')}return}if(form.id==='profile-edit-form'){const d=Object.fromEntries(new FormData(form));Object.assign(d,{age:account?.profile?.age,gender:account?.profile?.gender,height_cm:account?.profile?.height_cm,weight_kg:account?.profile?.weight_kg});api('/profile',{method:'POST',body:JSON.stringify(d)}).then(()=>{flash('Profile saved.');loadAccount()}).catch(error=>flash(error.message));return}if(form.id==='chat-form'){const input=form.elements.message,text=input.value.trim();if(!text)return;const messages=document.querySelector('#messages');messages.innerHTML+='<div class="bubble user">'+text.replace(/[<>]/g,'')+'</div>';input.value='';api('/ai',{method:'POST',body:JSON.stringify({message:text})}).then(r=>{messages.innerHTML+='<div class="bubble">'+String(r.answer).replace(/[<>]/g,'')+'</div>';messages.scrollTop=messages.scrollHeight}).catch(()=>{messages.innerHTML+='<div class="bubble">'+(account?botAnswer(text):'Sign in with Websim to save your NEXA conversation.')+'</div>';messages.scrollTop=messages.scrollHeight});return}if(form.dataset.form==='signup'){const d={full_name:form.elements.name.value,email:form.elements.email.value,age:Number(form.elements.age.value),gender:form.elements.gender.value,height_cm:Number(form.elements.height.value),weight_kg:Number(form.elements.weight.value),fitness_goal:form.elements.goal.value,fitness_level:form.elements.level.value};supabase.auth.signUp({email:d.email,password:form.elements.password.value,options:{data:{full_name:d.full_name},emailRedirectTo:window.location.origin+'/'}}).then(async({data,error})=>{if(error)throw error;if(!data.session){flash('Check your email to confirm your Supabase account, then log in.');location.hash='login';return}await api('/profile',{method:'POST',body:JSON.stringify(d)});flash('Your Supabase account is ready.');location.hash='dashboard';await loadAccount()}).catch(error=>flash(error.message));return}if(form.dataset.form==='login'){supabase.auth.signInWithPassword({email:form.elements.email.value,password:form.elements.password.value}).then(async({error})=>{if(error)throw error;location.hash='dashboard';await loadAccount()}).catch(error=>flash(error.message));return}if(form.dataset.form==='contact'){form.querySelector('.form-message').textContent='Thanks, '+form.elements.name.value+'!';form.reset()}});
window.addEventListener('hashchange',()=>{connectionTrainerId=null;render()});window.addEventListener('popstate',()=>render());loadAccount();
